// Builds every locked comp as a <section class="frame"> from shared parts. Rendered to PNG by render.mjs.
/* global BOTS */
const BG = '#0F1012';
const rgb = (h) => { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
const mix = (hex, t, base = BG) => { const a = rgb(base), b = rgb(hex); return '#' + a.map((v, i) => Math.round(v + (b[i] - v) * t).toString(16).padStart(2, '0')).join(''); };
const onColor = (hex) => { const l = rgb(hex).map((v) => { const s = v / 255; return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; }); const lum = 0.2126 * l[0] + 0.7152 * l[1] + 0.0722 * l[2]; return 1.05 / (lum + 0.05) >= (lum + 0.05) / 0.0057 ? '#FFFFFF' : '#0F1012'; };
const C = (bot) => BOTS[bot].color;
const ACCENT = '#8B7CF6', BAD = '#F06A6A', DIM = '#9298A0', TEXT = '#ECEDEF';

// ---- icons (24 grid, stroke) ----
