  chats: ico('<path d="M3.5 6.5A2.5 2.5 0 0 1 6 4h8a2.5 2.5 0 0 1 2.5 2.5v5A2.5 2.5 0 0 1 14 14H9l-3.5 3v-3H6a2.5 2.5 0 0 1-2.5-2.5z"/><path d="M19.5 9.5a2 2 0 0 1 1 1.8v4.2a2.5 2.5 0 0 1-2.5 2.5V20l-3.3-2.5H11"/>'),
  plus: ico('<path d="M12 5v14M5 12h14"/>', 2),
  up: ico('<path d="M12 19V5M6 11l6-6 6 6"/>', 2.6),
  check: ico('<path d="M5 12.5l4.5 4.5L19 7.5"/>', 2.2),
