// ---- parts ----
const sprite = (bot, mood = 'idle') => BOTS[bot].svg[mood] ?? BOTS[bot].svg.idle;
const av = (bot, s, mood) => `<div class="av" style="width:${s}px;height:${s}px;background:${mix(C(bot), 0.18)}">${sprite(bot, mood)}</div>`;
function stack(bots, s = 52) {
  const n = Math.min(bots.length, 3);
  const pos = n <= 2 ? [[0, 0, s * 0.64], [s * 0.36, s * 0.36, s * 0.64]] : [[s * 0.22, 0, s * 0.56], [0, s * 0.44, s * 0.56], [s * 0.44, s * 0.44, s * 0.56]];
  return `<div class="stack" style="width:${s}px;height:${s}px">${bots.slice(0, n).map((b, i) => `<div class="av" style="left:${pos[i][0]}px;top:${pos[i][1]}px;width:${pos[i][2]}px;height:${pos[i][2]}px;background:${mix(C(b), 0.22)}">${sprite(b)}</div>`).join('')}</div>`;
}
const status = () => `<div class="status"><span>9:41</span><div class="island"></div><div class="icons"><svg width="18" height="12" viewBox="0 0 18 12"><rect x="0" y="8" width="3" height="4" rx="1" fill="#ECEDEF"/><rect x="5" y="5.5" width="3" height="6.5" rx="1" fill="#ECEDEF"/><rect x="10" y="3" width="3" height="9" rx="1" fill="#ECEDEF"/><rect x="15" y="0" width="3" height="12" rx="1" fill="#ECEDEF"/></svg><div class="bat"><i></i></div></div></div>`;
const LOCK = (id) => `<div class="lock">LOCKED 2026-11-12 · ${id}</div>`;
const frames = [];
const iphone = (id, inner, extra = "") => frames.push(`<section class="frame iphone" id="${id}">${inner ? `<div class="col">${status()}${inner}</div>` : ""}${extra}<div class="home"></div>${LOCK(id)}</section>`);
const desktop = (id, inner, extra = '') => frames.push(`<section class="frame desktop" id="${id}">${inner}${extra}${LOCK(id)}</section>`);
const duoL = (id, inner, extra = '') => frames.push(`<section class="frame duo-l" id="${id}">${inner}${extra}${LOCK(id)}</section>`);
const ann = (x, y, t) => `<div class="ann" style="left:${x}px;top:${y}px">${t}</div>`;
const color = (c) => `style="color:${c}"`;
const safe = `<div style="height:26px;flex:none"></div>`;

// bot rows (iPhone)
function row(o) {
  const avatar = o.room ? stack(o.room, 52) : av(o.bot, 52, o.mood);
  const name = o.name ?? o.bot;
  return `<div class="row ${o.sel ? 'sel' : ''}">${avatar}<div class="body"><div class="l1"><div class="name">${name}${o.count ? `<span style="color:${DIM};font-weight:400"> · ${o.count}</span>` : ''}</div><div class="time">${o.time}</div><span class="chev">›</span></div><div style="display:flex;gap:8px;align-items:flex-start"><div class="pv ${o.kind ?? ''}" style="flex:1">${o.pv}</div>${o.badge ? `<span class="badge" style="margin-top:1px">${o.badge}</span>` : ''}</div></div></div>`;
}
function drow(o) {
  const avatar = o.room ? stack(o.room, 40) : av(o.bot, 40, o.mood);
  return `<div class="drow ${o.sel ? 'sel' : ''} ${o.hov ? 'hov' : ''}">${avatar}<div class="m"><div class="l1"><div class="n">${o.name ?? o.bot}${o.count ? `<span style="color:${DIM};font-weight:400"> · ${o.count}</span>` : ''}</div>${o.hov ? `<div class="dib" style="width:24px;height:20px;color:${DIM}">${I.dots}</div>` : `<div class="tm">${o.time}</div>`}</div><div style="display:flex;gap:6px;align-items:center"><div class="p ${o.kind ?? ''}" style="flex:1">${o.pv}</div>${o.badge ? `<span class="badge sm">${o.badge}</span>` : ''}</div></div></div>`;
}

const ROSTER = [
  { bot: 'chief', time: '9:41 AM', pv: 'Card 18 is with Design. I’ll merge the UI fixes once the comps are locked.' },
  { bot: 'design', time: '9:38 AM', pv: 'Thinking…', kind: 'live', mood: 'thinking' },
  { bot: 'assistant', time: '9:12 AM', pv: 'Wants to run a command: rm -rf ~/notes/old-drafts', badge: 'Needs you' },
  { bot: 'mobile', time: 'Yesterday', pv: 'Pushed app/notify-me. Tests pass; waiting on Design’s PASS.' },
  { bot: 'schedules', time: 'Tue', pv: 'No changes to the ops calendar this week.' },
  { bot: 'homelab', time: 'Mon', pv: 'Key rejected. Tap to pair again.', kind: 'err', mood: 'sleeping' },
  { bot: 'scout', time: 'Oct 30', pv: 'Here’s this week’s reading list: three long reads and a podcast.' },
];
const ROOM = { name: 'Ops room', room: ['chief', 'design', 'mobile'], count: 4, time: '9:44 AM', pv: '<b>chief:</b> Design, can you post the group chat comps here when they’re locked?' };

function listNav(right = '') {
  return `<div class="nav"><div class="grow"></div><div class="ibtn" ${color(ACCENT)}>${I.more}</div><div class="ibtn" ${color(ACCENT)}>${I.compose}</div>${right}</div><div class="largetitle">Dork Bot</div>`;
}
function sidebar(rows, opts = {}) {
  return `<div class="side"><div class="sidehd"><div class="t">Dork Bot</div><div class="dib" ${color(DIM)}>${I.more}</div><div class="dib ${opts.composeHover ? 'hov' : ''}" ${color(TEXT)}>${I.compose}</div></div><div style="display:flex;flex-direction:column;gap:2px">${rows.map(drow).join('')}</div></div>`;
}

// chat parts
function chatNav(bot, o = {}) {
  const c = C(bot);
  return `<div class="chatnav ${o.hair ? 'nav hair' : ''}"><div class="back" ${color(c)}>${I.back}<span>Bots</span></div><div class="grow" style="flex:1;display:flex;justify-content:center;min-width:0"><div class="ttl">${o.room ? stack(o.room, 32) : av(bot, 32, o.mood)}<div style="min-width:0"><div class="t1">${o.title ?? bot}</div><div class="t2">${o.sub ?? 'gemma4:31b · Dork'}</div></div></div></div>${o.right ?? `<div class="ibtn" ${color(c)}>${I.chats}</div><div class="ibtn" ${color(c)}>${I.more}</div>`}</div>`;
}
function dChatHd(bot, o = {}) {
  const c = C(bot);
  return `<div class="dhd">${o.toggle ? `<div class="dib" ${color(DIM)}>${I.sidebar}</div>` : ''}<div class="ttl" style="margin-left:4px">${o.room ? stack(o.room, 32) : av(bot, 32, o.mood)}<div style="min-width:0"><div class="t1">${o.title ?? bot}</div><div class="t2">${o.sub ?? 'gemma4:31b · Dork'}</div></div></div><div style="flex:1"></div>${o.right ?? `<div class="dib" ${color(c)}>${I.chats}</div><div class="dib" ${color(c)}>${I.more}</div>`}</div>`;
}
const mine = (bot, t, tint) => `<div class="mine" style="background:${tint ?? mix(C(bot), 0.3)}">${t}</div>`;
const chip = (t, live) => `<div class="chip">${live ? '<span class="spin"></span>' : `<span ${color(DIM)}>${I.check}</span>`}<span style="overflow:hidden;text-overflow:ellipsis">${t}</span><span class="chev">›</span></div>`;
const link = (bot, t) => `<a ${color(C(bot))}>${t}</a>`;
function composer(bot, o = {}) {
  const c = C(bot);
  const txt = o.text ? `<div class="txt">${o.text}</div>` : `<div class="txt ph">${o.ph ?? `Message ${bot}`}</div>`;
  const action = o.stop ? `<div class="stop"><i></i></div>` : o.text ? `<div class="send" style="background:${c};color:${onColor(c)}">${I.up}</div>` : '';
  return `<div class="composer"><div class="plus" ${color(DIM)}>${I.plus}</div><div class="field">${txt}${action}</div></div>`;
}
const typing = (bot) => `<div class="working">${av(bot, 28, 'thinking')}<div class="typing"><i></i><i></i><i></i></div></div>`;
const EARLIER = (bot) => `${mine(bot, 'what’s on my calendar tomorrow?')}<div class="reply"><p>Two things: dentist at 10:30 AM, and the team call at 2 PM. Nothing after 4.</p></div>${mine(bot, 'move the call to 3 if everyone’s free')}${chip('Used Calendar · 2 steps')}<div class="reply"><p>Everyone’s free at 3. I moved it and sent the update.</p></div>`;

