// ================= FIX 5: approvals =================
const approval = (bot, o = {}) => { const c = C(bot); const h = o.desktop ? 'height:36px;' : ''; const grid = o.desktop ? 'style="grid-template-columns:repeat(4,auto);justify-content:start"' : ''; const btns = [`<div class="btn" style="${h}background:${c};color:${onColor(c)}">Allow once</div>`, `<div class="btn outline" style="${h}border-color:${BAD};color:${BAD}">Deny</div>`, `<div class="btn" style="${h}background:${mix(c, .2)};color:${TEXT}">Allow in this chat</div>`, `<div class="btn" style="${h}background:${mix(c, .2)};color:${TEXT}">Always allow</div>`]; const order = o.desktop ? [btns[0], btns[2], btns[3], btns[1]] : btns; return `<div class="approval" style="border-color:${mix(c, .55)}"><div class="h">${av(bot, 24)}<div><div class="t">${o.title ?? 'Run this command?'}</div><div class="s">${o.sub ?? `${bot} needs your OK`}</div></div></div><div class="cmd">${o.cmd ?? 'rm -rf ~/notes/old-drafts'}</div><div class="why">${o.why ?? 'Hermes flagged it: recursive delete.'}</div><div class="grid2" ${grid}>${order.join('')}</div><div class="foot"><span>Answers right away. No answer counts as Deny.</span><span>4:32</span></div></div>`; };
