const g = (bot, t, body, o = {}) => `<div class="gmsg ${o.cont ? 'cont' : ''} ${o.needs ? 'needs' : ''}"><div class="gutter">${o.cont ? '' : av(bot, 28)}</div><div style="flex:1;min-width:0">${o.cont ? '' : `<div class="who"><span class="n" ${color(C(bot))}>${bot}</span><span class="t">${t}</span>${o.needs ? `<span class="badge sm" style="margin-left:4px">Needs you</span>` : ''}</div>`}<div class="reply">${body}</div></div></div>`;
const at = (bot) => `<span class="at" ${color(C(bot))}>@${bot}</span>`;
const atYou = `<span class="at" ${color(ACCENT)}>@you</span>`;
const userTint = mix(ACCENT, 0.3);
const roomNav = (o = {}) => chatNav('chief', { room: ['chief', 'design', 'mobile'], title: 'Ops room', sub: 'chief, design, mobile, schedules', right: `<div class="ibtn" ${color(ACCENT)}>${I.people}</div><div class="ibtn" ${color(ACCENT)}>${I.more}</div>`, ...o }).replace(/<div class="back" style="color:[^"]*">/, `<div class="back" ${color(ACCENT)}>`);
const dRoomHd = () => dChatHd('chief', { toggle: true, room: ['chief', 'design', 'mobile'], title: 'Ops room', sub: 'chief, design, mobile, schedules', right: `<div class="dib" ${color(ACCENT)}>${I.people}</div><div class="dib" ${color(ACCENT)}>${I.gear}</div>` });
const roomComposer = (o = {}) => composer('chief', o).replace(/Message chief/, 'Message Ops room').replace(/background:#F25F5C;color:[^"]*"/, `background:${ACCENT};color:#fff"`);
const strip = (items, extra = '') => `<div class="strip">${items.map(([b, t]) => `<span class="who">${av(b, 20, 'thinking')}${b}</span><span>${t}</span>`).join('<span style="color:#4b4f56">·</span>')}<span style="flex:1"></span>${extra}</div>`;
const ROOM_EARLIER = `${g('schedules', '9:02 AM', '<p>Morning. No calendar changes for the team today.</p>')}${g('chief', '9:05 AM', `<p>Thanks. ${at('mobile')} where’s Notify me?</p>`)}${g('mobile', '9:06 AM', '<p>PR is up, tests pass. Waiting on Design’s PASS.</p>')}`;
const ROOM_TX = `${ROOM_EARLIER}<div class="stamp"><b>Today</b> 9:30 AM</div>${mine('chief', `${at('design')} where are the group chat comps?`, userTint)}${g('design', '9:31 AM', '<p>Drawing them now: the room row, New group chat, the room itself, @-mentions, approvals and Stop. Posting here when they’re locked.</p>')}${g('chief', '9:32 AM', `<p>Good. ${at('mobile')} card 8 starts after the UI fixes, so hold until then.</p>`)}${g('mobile', '9:33 AM', '<p>Holding. I’ll pick up card 19 first.</p>')}`;

iphone('g1-list--iphone', `${listNav()}<div class="rows">${row({ ...ROOM, badge: 'Needs you' })}${ROSTER.slice(0, 6).map(row).join('')}</div>`,
  ann(84, 186, 'room: member stack (or room picture) · name · member count') + ann(84, 236, 'preview: “speaker: text”') + ann(250, 64, 'compose → New bot / New group chat'));
desktop('g1-room--desktop', `<div class="dwin">${sidebar([{ ...ROOM, sel: true }, ...ROSTER.slice(0, 6)])}<div class="main">${dRoomHd()}<div class="transcript dcol">${ROOM_TX}</div>${'<div class="dcol">' + strip([['design', 'is thinking'], ['mobile', 'is working']], '<span>12 s</span>') + '</div>'}<div class="dcomp dcol">${roomComposer({ stop: true })}</div></div></div>`,
  ann(330, 4, 'room rows sit in the same recency-ordered list') + ann(1020, 60, 'members · group settings') + ann(380, 700, 'per-member working strip; tap → Activity'));
iphone('g2-new-room--iphone', '', `<div class="under"><div class="col">${status()}${listNav()}<div class="rows">${ROSTER.map(row).join('')}</div></div></div><div class="dim"></div><div class="sheet"><div class="grabber"></div><div class="sheethd"><div class="tbtn" ${color(ACCENT)}>Cancel</div><div class="center"><div class="a">New group chat</div></div><div class="grow"></div><div class="tbtn b" ${color(ACCENT)}>Create</div></div><div class="picbtn">${stack(['chief', 'design', 'mobile'], 60)}<div style="position:absolute;right:-2px;bottom:-2px;width:28px;height:28px;border-radius:14px;background:var(--raised);display:flex;align-items:center;justify-content:center;color:${TEXT}"><span style="width:16px;height:16px;display:flex">${I.camera}</span></div></div><div style="text-align:center;font:400 13px var(--font);color:${ACCENT};margin-bottom:12px">Add picture (optional)</div><div class="field2">Ops room</div><div class="sec">Members · 4 of 6</div><div class="group">${[['chief', 1, 'Chief of staff'], ['design', 1, 'UI direction and ship QA'], ['mobile', 1, 'Builds the app'], ['schedules', 1, 'Live data and feeds'], ['assistant', 0, 'Email, calendar, reminders'], ['homelab', 0, 'b-lab services']].map(([b, on, j]) => `<div class="gr ic">${av(b, 32)}<div class="m"><div class="n b">${b}</div><div class="d">${j}</div></div>${on ? `<div class="ck-on" style="background:${ACCENT};color:#fff"><span style="width:14px;height:14px;display:flex">${I.check}</span></div>` : '<div class="ck-off"></div>'}</div>`).join('')}</div><div class="note">2 to 6 bots. Each one replies when it has something to add; @mention a bot to ask just that one.</div></div>`,
  ann(300, 112, 'Create off until a name and 2+ bots') + ann(28, 455, 'counter in the section header; 7th tap blocked at 6'));
desktop('g2-new-room--desktop', `<div class="dwin">${sidebar(ROSTER.slice(0, 7), { composeHover: true })}<div class="main">${dChatHd('chief', { toggle: true, sub: 'claude-opus-5-5 · Anthropic' })}</div></div>`,
  `<div class="panelwrap"><div class="panel" style="height:640px"><div class="panelhd"><div style="flex:1"><div class="a">New group chat</div></div><div class="dib" ${color(DIM)}>${I.x}</div></div><div style="display:flex;gap:16px;align-items:center;padding:20px 20px 4px">${stack(['chief', 'design', 'mobile'], 64)}<div style="flex:1"><div style="font:400 12px var(--font);color:${DIM};margin-bottom:6px">Name</div><div class="field2" style="margin:0;font-size:15px;height:40px">Ops room</div><div style="font:400 12px var(--font);color:${ACCENT};margin-top:6px">Add picture (optional)</div></div></div><div class="dsec">Members · 4 of 6</div><div class="dgroup">${[['chief', 1, 'Chief of staff'], ['design', 1, 'UI direction and ship QA'], ['mobile', 1, 'Builds the app'], ['schedules', 1, 'Live data and feeds'], ['assistant', 0, 'Email, calendar, reminders'], ['homelab', 0, 'b-lab services']].map(([b, on, j]) => `<div class="dgr ic" style="min-height:48px">${av(b, 30)}<div class="m"><div class="n">${b}</div><div class="d">${j}</div></div>${on ? `<div class="ck-on" style="width:20px;height:20px;background:${ACCENT};color:#fff"><span style="width:12px;height:12px;display:flex">${I.check}</span></div>` : '<div class="ck-off" style="width:20px;height:20px"></div>'}</div>`).join('')}</div><div style="flex:1"></div><div style="display:flex;justify-content:flex-end;gap:8px;padding:14px 20px;border-top:.5px solid var(--border)"><div class="dsbtn" style="background:var(--raised);color:${TEXT}">Cancel</div><div class="dsbtn" style="background:${ACCENT};color:#fff">Create group chat</div></div></div></div>`);
iphone('g3-room--iphone', `${roomNav()}<div class="transcript">${ROOM_TX}</div>${strip([['design', 'is thinking'], ['mobile', 'is working']], '<span>12 s</span>')}${roomComposer({ stop: true })}${safe}`,
  ann(16, 300, 'each reply: avatar 28 + name 14 semibold in bot color + time 12') + ann(16, 735, 'working strip 36: who + what, elapsed after 10 s') + ann(300, 112, 'Members · Group settings'));
iphone('g4-mention--iphone', `${roomNav()}<div class="transcript">${ROOM_EARLIER}${g('design', '9:31 AM', '<p>Drawing them now. Posting here when they’re locked.</p>')}${g('chief', '9:32 AM', `<p>Good. ${at('mobile')} card 8 starts after the UI fixes.</p>`)}</div>${roomComposer({ text: `@de` })}<div class="kbd">${['qwertyuiop', 'asdfghjkl', 'zxcvbnm'].map((r, i) => `<div class="kr">${i === 2 ? '<div class="k w">⇧</div>' : ''}${[...r].map((k) => `<div class="k">${k}</div>`).join('')}${i === 2 ? '<div class="k w">⌫</div>' : ''}</div>`).join('')}<div class="kr"><div class="k w">123</div><div class="k w">☺</div><div class="k sp">space</div><div class="k rt">return</div></div></div>`,
  `<div class="pop" style="left:12px;right:12px;bottom:351px;padding:4px 0">${[['design', 'UI direction and ship QA', true]].map(([b, j, on]) => `<div class="mention ${on ? 'on' : ''}">${av(b, 28)}<span class="n">${b}</span><span class="h">@${b}</span><span class="j">${j}</span></div>`).join('')}<div style="height:.5px;background:#343840;margin:4px 12px"></div><div class="mention"><div class="av" style="width:28px;height:28px;background:${mix(ACCENT, .25)};color:${TEXT}"><span style="width:16px;height:16px;display:flex">${I.people}</span></div><span class="n">Everyone</span><span class="h">@all</span><span class="j">All 4 members</span></div></div>` + ann(20, 380, '“@” opens it; filters as you type; return or tap inserts @handle + space'));
desktop('g4-mention--desktop', `<div class="dwin">${sidebar([{ ...ROOM, sel: true }, ...ROSTER.slice(0, 6)])}<div class="main">${dRoomHd()}<div class="transcript dcol">${ROOM_TX}</div><div class="dcomp dcol" style="position:relative">${roomComposer({ text: '@' })}<div class="pop" style="left:52px;bottom:64px;width:360px;padding:4px 0">${[['chief', 'Chief of staff', 1], ['design', 'UI direction and ship QA'], ['mobile', 'Builds the app'], ['schedules', 'Live data and feeds']].map(([b, j, on]) => `<div class="mention ${on ? 'on' : ''}" style="height:40px">${av(b, 26)}<span class="n" style="font-size:14px">${b}</span><span class="h">@${b}</span><span class="j">${j}</span></div>`).join('')}<div style="height:.5px;background:#343840;margin:4px 12px"></div><div class="mention" style="height:40px"><div class="av" style="width:26px;height:26px;background:${mix(ACCENT, .25)};color:${TEXT}"><span style="width:15px;height:15px;display:flex">${I.people}</span></div><span class="n" style="font-size:14px">Everyone</span><span class="h">@all</span></div></div></div></div></div>`,
  ann(420, 560, '↑↓ to move, Enter/Tab to insert, Esc to close'));
const roomApproval = approval('mobile', { title: 'Run this command?', sub: 'mobile needs your OK in Ops room', cmd: 'git push origin app/ui-polish', why: 'Hermes flagged it: pushes to GitHub.' });
iphone('g5-needs-you--iphone', `${roomNav()}<div class="transcript">${ROOM_EARLIER}${g('design', '9:41 AM', `<p>Comps are locked. ${atYou} one call for you: should a room’s Stop also hold bots that haven’t started yet?</p>`, { needs: true })}${g('mobile', '9:42 AM', '<p>Pulling the comps into the repo.</p>')}${roomApproval}</div>${strip([['mobile', 'is waiting for your OK']])}${roomComposer({ stop: true })}${safe}`,
  ann(16, 150, '@you: red bar + Needs you on the message; row badge until answered') + ann(16, 650, 'approval: same card as 1:1, says which bot and room; one tap answers'));
desktop('g5-needs-you--desktop', `<div class="dwin">${sidebar([{ ...ROOM, sel: true, badge: 'Needs you', pv: '<b>mobile:</b> wants to run a command' }, ...ROSTER.slice(0, 6)])}<div class="main">${dRoomHd()}<div class="transcript dcol">${ROOM_EARLIER}${g('chief', '9:40 AM', `<p>${at('design')} status on the comps?</p>`)}${g('design', '9:41 AM', `<p>Comps are locked. ${atYou} one call for you: should a room’s Stop also hold bots that haven’t started yet?</p>`, { needs: true })}${g('mobile', '9:42 AM', '<p>Pulling the comps into the repo.</p>')}<div style="padding-left:36px;max-width:556px">${approval('mobile', { title: 'Run this command?', sub: 'mobile needs your OK in Ops room', cmd: 'git push origin app/ui-polish', why: 'Hermes flagged it: pushes to GitHub.', desktop: true })}</div></div><div class="dcol">${strip([['mobile', 'is waiting for your OK']])}</div><div class="dcomp dcol">${roomComposer({ stop: true })}</div></div></div>`);
iphone('g6-held--iphone', `${roomNav()}<div class="transcript">${ROOM_TX}<div class="sysline">You stopped the room. design and mobile are held.</div></div><div class="strip"><span class="held">${av('design', 18, 'sleeping')}Held</span><span class="held">${av('mobile', 18, 'sleeping')}Held</span><span style="flex:1"></span><span style="color:${ACCENT};font-weight:600">Resume all</span></div>${roomComposer({ ph: '@mention a bot, or @all to resume' })}${safe}`,
  ann(16, 735, 'held chips; Resume all = sends “@all resume”') + ann(40, 690, 'system line 13 dim, centered'));
desktop('g6-held--desktop', `<div class="dwin">${sidebar([{ ...ROOM, sel: true, pv: 'You stopped the room.' }, ...ROSTER.slice(0, 6)])}<div class="main">${dRoomHd()}<div class="transcript dcol">${ROOM_TX}<div class="sysline">You stopped the room. design and mobile are held.</div></div><div class="dcol"><div class="strip"><span class="held">${av('design', 18, 'sleeping')}Held</span><span class="held">${av('mobile', 18, 'sleeping')}Held</span><span style="flex:1"></span><span style="color:${ACCENT};font-weight:600">Resume all</span></div></div><div class="dcomp dcol">${roomComposer({ ph: '@mention a bot, or @all to resume' })}</div></div></div>`);

// Duo open, landscape: same as desktop sidebar, iOS type sizes.
duoL('01-bot-list--duo-landscape', `<div class="dwin" style="padding-right:84px"><div class="side" style="width:300px"><div style="height:24px"></div><div class="sidehd"><div class="t" style="font-size:20px">Dork Bot</div><div class="dib" style="color:${ACCENT};width:44px;height:44px">${I.more}</div><div class="dib" style="color:${ACCENT};width:44px;height:44px">${I.compose}</div></div>${[{ ...ROSTER[0], sel: true }, ROSTER[1], ROSTER[2], ROSTER[3], ROSTER[4], ROSTER[5]].map(drow).join('').replace(/font: 600 15px/g, '')}</div><div class="main">${dChatHd('chief', { toggle: true, sub: 'claude-opus-5-5 · Anthropic' }).replace('class="dhd"', 'class="dhd" style="margin-top:24px"')}<div class="transcript" style="padding:12px 20px 12px">${mine('chief', 'can we get group chats in the app?')}${chip('Used Trello, Terminal · 7 steps')}<div class="reply"><p>Yes. Hermes already has group rooms built in, so Dork Bot will use those.</p></div></div>${composer('chief')}<div style="height:26px"></div></div></div><div style="position:absolute;right:0;top:0;bottom:0;width:84px;background:#08090a"></div>`,
  ann(310, 4, 'open Duo landscape: desktop sidebar layout, iOS sizes (44 hit, 17 body)'));

// ================= FIX 11: routine cards (card 24) =================
const chevR = `<svg viewBox="0 0 9 15" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M1.5 1.5 7.5 7.5l-6 6"/></svg>`;
function rcard(bot, o = {}) {
  const c = C(bot);
  const vars = `--rf:${mix(c, 0.08)};--rb:${mix(c, 0.22)};--rh:${mix(c, 0.22)};--rhb:${mix(c, 0.6)}`;
  const head = `<div class="rh"><div class="ri" style="background:${mix(c, 0.18)};color:${c}">${I.clock}</div><div class="rm"><div class="rl1"><div class="rn">Friday packing reminder</div><div class="rt">Fri 8:00 PM</div></div>${o.open ? '' : '<div class="rp">Saturday hike: dry until about 2 PM, then showers. Pack a rain jacket, bring water, start early</div>'}</div><div class="rc">${chevR}</div></div>`;
  const body = o.open ? `<div class="rbody"><div class="reply"><p>Saturday hike: dry until about 2 PM, then showers.</p><ul><li>Pack a rain jacket</li><li>Bring water</li><li>Start early</li></ul></div></div>` : '';
  return `<div class="rcard ${o.open ? 'open' : ''} ${o.hl ? 'hl' : ''}" style="${vars}">${head}${body}</div>`;
}
const R_CTX = (bot, o) => `${mine(bot, 'remind me friday night to pack a rain jacket anyway')}<div class="reply"><p>Done. I’ll message you Friday at 8 PM.</p></div><div class="stamp"><b>Friday</b> 8:00 PM</div>${rcard(bot, o)}${mine(bot, 'thanks, got it')}<div class="reply"><p>Anytime. Want me to check the forecast again Saturday morning?</p></div>`;
const R_ANN = {
  collapsed: ann(20, 276, 'collapsed: full width, ~59 tall, r16, fill mix(bot,.08), icon disc 28'),
  expanded: ann(20, 260, 'expanded: › rotated 90°, preview hides, 0.5 divider, Markdown 17/24'),
  highlight: ann(20, 250, 'highlight ≈1 s: fill mix(bot,.22), border 1.5 mix(bot,.6)'),
};
for (const [key, o] of [['collapsed', {}], ['expanded', { open: true }], ['highlight', { open: true, hl: true }]]) {
  iphone(`24-routine-${key}--iphone`, `${chatNav('assistant')}<div class="transcript">${R_CTX('assistant', o)}</div>${composer('assistant')}${safe}`, R_ANN[key]);
  desktop(`24-routine-${key}--desktop`, `<div class="dwin">${sidebar([ROSTER[0], ROSTER[1], { ...ROSTER[2], sel: true, badge: null, pv: 'Routine · Friday packing reminder' }, ROSTER[3], ROSTER[4], ROSTER[5], ROSTER[6]])}<div class="main">${dChatHd('assistant', { toggle: true })}<div class="transcript dcol">${R_CTX('assistant', o)}</div><div class="dcomp dcol">${composer('assistant')}</div></div></div>`);
}

document.body.innerHTML = frames.join('\n');
